/// <summary>
///     Data provider class for <c>AVABPMasterDataReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Data provider class for the <c>AVABPMasterDataReport</c> SSRS Report.
/// </remarks>
[
    //SRSReportQueryAttribute(queryStr(AVAKCS_KBVBuildingProjectTableQuery)),
    SRSReportParameterAttribute(classStr(AVABPMasterDataReportContract))
]
class AVABPMasterDataReportDP extends SrsReportDataProviderPreProcess //SRSReportDataProviderBase
{
    AVABPMasterDataReportHeaderTmp      clsHeaderTmp;
    AVABPMasterDataReportHeaderTmp      clsHeaderTmpBase;
    AVABPMasterDataReportActivityTmp    clsActivityTmp;
    AVABPMasterDataReportQuotationTmp   clsQuotationTmp;
    AVABPMasterDataReportRelationTmp    clsRelationTmp;
    AVABPMasterDataReportRequestTmp     clsRequestTmp;

    CompanyInfo                         clsCompanyInfo;
    CompanyImage                        clsCompanyLogo;
    Bitmap                              clsCompanyLogoBitmap;
    container                           clsAllBPCompanies;
    container                           clsAllBPCompaniesAll;

    KCS_KBVBuildingProjectTable         clsKCS_KBVBuildingProjectTable;

    AVABPMasterDataReportContract       clsAVABPMasterDataReportContract;
    RefRecId                            clsBuildingProjectRecId;
    KCS_KBVBuildingProjectID            clsBuildingProjectId;
    boolean                             clsShowQuotations;
    boolean                             clsShowRelations;
    boolean                             clsShowRequests;

    int                                 clsAdditionalInfoLevel;

}

