/// <summary>
///     AVA <c>initialize</c> method.
/// </summary>
/// <remarks>
///     This method can be overridden by application developers to add any initialization logic needed.
///     This method is invoked by framework before <c>processReport</c> report is invoked.
/// </remarks>
public void initialize()
{
    this.setContractAndParamValues();
}

/// <summary>
///     AVA <c>processReport</c> method.
/// </summary>
public void processReport()
{
    Query                   locQuery;
    QueryBuildDataSource    locQueryBuildDataSource;
    QueryRun                locQueryRun;
    QueryBuildRange         locQueryBuildRange;

    //locQuery = this.parmQuery();
    locQuery                = new Query();
    locQueryBuildDataSource = locQuery.addDataSource(tableNum(KCS_KBVBuildingProjectTable));

    if (clsBuildingProjectId)
    {
        locQueryBuildRange = locQuery.dataSourceTable(tableNum(KCS_KBVBuildingProjectTable)).addRange(fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID));
        locQueryBuildRange.value(SysQuery::value(clsBuildingProjectId));
    }

    locQueryRun    = new queryRun(locQuery);

    ttsbegin;
    while (locQueryRun.next())
    {
        clsKCS_KBVBuildingProjectTable  = locQueryRun.get(tableNum(KCS_KBVBuildingProjectTable));
        // insert data
        if(clsKCS_KBVBuildingProjectTable.RecId)
        {
            this.insertTmpTableData();
        }
    }
    ttscommit;
}

