/// <summary>
///     Set the database transaction connection for a record from the connection associated with the report.
/// </summary>
/// <param name = "_reportRecord">
///     A record to set database transaction for.
/// </param>
final protected void setTransactionConnection(Common _reportRecord)
{
    var connection = this.parmUserConnection();

    if (connection)
    {
        _reportRecord.setConnection(connection);
    }
}

/// <summary>
///     AVA <c>processReport</c> method.
/// </summary>
public void setContractAndParamValues()
{
    DataAreaId locDataAreaId;


    clsCompanyInfo              = CompanyInfo::find();
    clsCompanyLogo              = CompanyImage::findByRecord(CLScompanyInfo);
    clsCompanyLogoBitmap        = clsCompanyLogo.Image;
    clsAllBPCompaniesAll        = AVAKBVBuildingProjectHelper::getAllBPCompanies();
    clsAllBPCompanies           = clsAllBPCompaniesAll;

    clsAVABPMasterDataReportContract = this.parmDataContract() as AVABPMasterDataReportContract;

    if(clsAVABPMasterDataReportContract.parmPrintMode() == SalesTableMode::Simple)
    {
        locDataAreaId           = AVASalesParameters::find().SecondaryDataAreaIdBPRequests;
        clsAllBPCompanies       = conNull();
        if(locDataAreaId)
        {
            clsAllBPCompanies   = [curext(), locDataAreaId];
        }
        else
        {
            clsAllBPCompanies   = [curext()];
        }
    }

    clsBuildingProjectRecId     = clsAVABPMasterDataReportContract.parmBuildingProjectRefRecId();
    clsBuildingProjectId        = clsAVABPMasterDataReportContract.parmKCS_KBVBuildingProjectID();
    clsShowQuotations           = clsAVABPMasterDataReportContract.parmShowQuotations();
    clsShowRelations            = clsAVABPMasterDataReportContract.parmShowRelations();
    clsShowRequests             = clsAVABPMasterDataReportContract.parmShowRequests();
}

/// <summary>
///     AVA <c>insertTmpTableData</c> method.
/// </summary>
public void insertTmpTableData()
{
    if(clsKCS_KBVBuildingProjectTable.RecId)
    {
        this.insertTmpTableDataHeader();

        this.insertTmpTableDataActivities();

        if(clsShowRequests)
        {
            this.insertTmpTableDataRequests();
        }

        if(clsShowRelations)
        {
            if(clsAVABPMasterDataReportContract.parmPrintMode() == SalesTableMode::Advanced)
            {
                this.insertTmpTableDataRelations();
            }
        }

        if(clsShowQuotations)
        {
            this.insertTmpTableDataQuotations();
        }
    }
}

/// <summary>
///    AVA <c>insertTmpTableDataQuotations</c> method.
/// </summary>
public void insertTmpTableDataHeader()
{
    LogisticsAddressing         locLogisticsAddressing;
    String255                   locBPKnownBy;
    KCS_KBVBuildingProjectMemo  locKCS_KBVBuildingProjectMemo;

    locLogisticsAddressing = '';

    if(clsKCS_KBVBuildingProjectTable.RecId)
    {
        this.setTransactionConnection(clsHeaderTmp);

        clsHeaderTmp.AdditionalInfoNo = 0;
        // address info
        if (clsKCS_KBVBuildingProjectTable.AddressCountryRegionId)
        {
            locLogisticsAddressing += clsKCS_KBVBuildingProjectTable.AddressCountryRegionId;
        }

        if (locLogisticsAddressing && clsKCS_KBVBuildingProjectTable.AddressZipCodeId)
        {
            locLogisticsAddressing += ' - ';
        }
        locLogisticsAddressing += clsKCS_KBVBuildingProjectTable.AddressZipCodeId;

        if (locLogisticsAddressing && clsKCS_KBVBuildingProjectTable.AddressCity)
        {
            locLogisticsAddressing += " ";
        }
        locLogisticsAddressing += clsKCS_KBVBuildingProjectTable.AddressCity;

        if (locLogisticsAddressing && clsKCS_KBVBuildingProjectTable.AddressStreet)
        {
            locLogisticsAddressing += " - ";
        }
        locLogisticsAddressing += clsKCS_KBVBuildingProjectTable.AddressStreet;

        locBPKnownBy = this.buildingProjectKnownBy();


        clsHeaderTmp.KCS_KBVBuildingProjectID   = clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
        clsHeaderTmp.KCS_KBVSubject             = clsKCS_KBVBuildingProjectTable.KCS_KBVSubject;
        clsHeaderTmp.LogisticsAddressing        = locLogisticsAddressing;
        clsHeaderTmp.smmSalesDistrictId         = clsKCS_KBVBuildingProjectTable.smmSalesDistrictId; //@SYS81474
        clsHeaderTmp.BPKnownIn                  = locBPKnownBy;
        clsHeaderTmp.CompanyLogo                = clsCompanyLogoBitmap;
        clsHeaderTmp.ProbabilityId              = clsKCS_KBVBuildingProjectTable.smmQuotationProbabilityId;
        if(clsKCS_KBVBuildingProjectTable.smmQuotationProbabilityId)
        {
            clsHeaderTmp.ProbabilityDescription     = smmQuotationProbabilityGroup::find(clsKCS_KBVBuildingProjectTable.smmQuotationProbabilityId).Description;
        }
        select firstonly locKCS_KBVBuildingProjectMemo
        where locKCS_KBVBuildingProjectMemo.KCS_KBVBuildingProjectID == clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
        if(locKCS_KBVBuildingProjectMemo.RecId)
        {
            clsHeaderTmp.Memo = locKCS_KBVBuildingProjectMemo.Memo;
        }
        clsHeaderTmp.insert();

        Buf2Buf(clsHeaderTmp, clsHeaderTmpBase);
        if(clsHeaderTmp.RecId)
        {
            this.insertTmpTableDataHeaderMemo();
        }
    }
}

public void insertTmpTableDataHeaderMemo()
{
    KCS_KBVBuildingProjectMemo locKCS_KBVBuildingProjectMemo;

    clsAdditionalInfoLevel = 100;

    while select locKCS_KBVBuildingProjectMemo
    where locKCS_KBVBuildingProjectMemo.KCS_KBVBuildingProjectID == clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
    {
        if(locKCS_KBVBuildingProjectMemo.Memo != '')
        {
            clsHeaderTmp.AdditionalInfoNo   = clsAdditionalInfoLevel;
            clsHeaderTmp.Memo               = locKCS_KBVBuildingProjectMemo.Memo;
            clsHeaderTmp.insert();
            clsAdditionalInfoLevel++;
        }
    }
    clsHeaderTmp.Memo               = '';
}

/// <summary>
///    AVA <c>insertTmpTableDataActivities</c> method.
/// </summary>
public void insertTmpTableDataActivities()
{
    KCS_KBVActivitiesForBP  locKCS_KBVActivitiesForBP;
    smmActivities           locsmmActivities;
    smmActivityTypeGroup    locsmmActivityTypeGroup;
    smmActivitypeTypeDescription locsmmActivitypeTypeDescription;

    if(clsKCS_KBVBuildingProjectTable.RecId)
    {
        this.setTransactionConnection(clsActivityTmp);

        clsAdditionalInfoLevel = 200;

        while select crosscompany : clsAllBPCompanies locKCS_KBVActivitiesForBP
        where   locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID == clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
            join    locsmmActivities
            where   locsmmActivities.ActivityNumber == locKCS_KBVActivitiesForBP.smmActivityNumber
        {
            clsActivityTmp.clear();
            clsActivityTmp.AdditionalInfoNo         = clsAdditionalInfoLevel;
            clsActivityTmp.KCS_KBVBuildingProjectID = clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;

            clsActivityTmp.DirDataAreaId            = locKCS_KBVActivitiesForBP.DataAreaId;
            clsActivityTmp.ActivityNumber           = locsmmActivities.ActivityNumber;                          // smmActivityNumber @SYS81290
            clsActivityTmp.Category                 = locsmmActivities.Category;                                //smmActivityCategory   //@SYS81431
            clsActivityTmp.DateStart                = locsmmActivities.startDate();                             //@NDX:NXADateTimeStart
            clsActivityTmp.DateEnd                  = locsmmActivities.endDate();                               //@NDX:NXADateTimeEnd
            clsActivityTmp.TypeId                   = locsmmActivities.TypeId;                                  //smmActivityTypeId @SYS81318
            if(locsmmActivities.TypeId)
            {
                select firstonly locsmmActivityTypeGroup
                    where locsmmActivityTypeGroup.TypeId == locsmmActivities.TypeId;
                if(locsmmActivityTypeGroup.Description)
                {
                    locsmmActivitypeTypeDescription = locsmmActivityTypeGroup.Description;
                }
                else
                {
                    locsmmActivitypeTypeDescription = locsmmActivityTypeGroup.TypeId;
                }
            }
            clsActivityTmp.TypeDescription          = locsmmActivitypeTypeDescription;                          //smmActivitypeTypeDescription   // @SYS25589
            clsActivityTmp.AVAFieldWorker           = locsmmActivities.AVAFieldWorker;                          // @NDX:NXAFieldWorker
            clsActivityTmp.AVAFieldWorkerName       = HCMWorker::find(locsmmActivities.AVAFieldWorker).name();  // @NDX:NXAFieldWorker

            if(clsAVABPMasterDataReportContract.parmPrintMode() == SalesTableMode::Advanced)
            {
                clsActivityTmp.UserMemo                 = locsmmActivities.UserMemo;                                //@SYS318221
            }

            clsActivityTmp.insert();
            clsAdditionalInfoLevel++;
        }
    }
}

/// <summary>
///    AVA <c>insertTmpTableDataRequests</c> method.
/// </summary>
public void insertTmpTableDataRequests()
{
    KCS_KBVRequestTable locKCS_KBVRequestTable;
    DirPartyTable       locDirPartyTable;
    ContactPerson       locContactPerson;
    PhoneMobile         locPhoneMobile;
    Phone               locPhone;
    Email               locEmail;
    Addressing          locAddressing;

    if(clsKCS_KBVBuildingProjectTable.RecId)
    {
        this.setTransactionConnection(clsRequestTmp);

        clsAdditionalInfoLevel = 300;

        while select crosscompany : clsAllBPCompanies locKCS_KBVRequestTable
        where locKCS_KBVRequestTable.KCS_KBVBuildingProjectID == clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
        {
            clsRequestTmp.clear();
            clsRequestTmp.AdditionalInfoNo          = clsAdditionalInfoLevel;
            clsRequestTmp.KCS_KBVBuildingProjectID  = clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;

            clsRequestTmp.DirDataAreaId             = locKCS_KBVRequestTable.DataAreaId;
            clsRequestTmp.KCS_KBVRequestID          = locKCS_KBVRequestTable.KCS_KBVRequestID;

            locDirPartyTable                        = locKCS_KBVRequestTable.dirPartyTableOrganization();
            clsRequestTmp.DirPartyId                = locDirPartyTable.RecId;
            clsRequestTmp.DirPartyTableName         = locDirPartyTable.Name;

            clsRequestTmp.CustRef                   = locKCS_KBVRequestTable.CustRef;               // @SYS23010
            clsRequestTmp.KCS_KBVPriority           = locKCS_KBVRequestTable.KCS_KBVPriority;       // @NDX:NXARequestPriority
            clsRequestTmp.KCS_KBVRequestStatus      = locKCS_KBVRequestTable.KCS_KBVRequestStatus;  // @SYS80127
            clsRequestTmp.KCS_KBVDeclinedMemo       = locKCS_KBVRequestTable.KCS_KBVDeclinedMemo;   // @SYS116754

            locContactPerson                        = locKCS_KBVRequestTable.contactPerson();
            if(locContactPerson.RecId)
            {
                clsRequestTmp.ContactPersonId       = locContactPerson.ContactPersonId;
                clsRequestTmp.ContactPersonName     = locContactPerson.personName();
            }
            locPhoneMobile                          = locKCS_KBVRequestTable.displayMobile();        // @SYS27784
            if(locPhoneMobile)
            {
                if(clsRequestTmp.ContactInformation)
                {
                    clsRequestTmp.ContactInformation += ', ';
                }
                clsRequestTmp.ContactInformation += strFmt("@SYS82282", "@SYS27784") + ': ' + locPhoneMobile;
            }
            locPhone                                = locKCS_KBVRequestTable.displayPhone();        // @SYS7869
            if(locPhone)
            {
                if(clsRequestTmp.ContactInformation)
                {
                    clsRequestTmp.ContactInformation += ', ';
                }
                clsRequestTmp.ContactInformation += strFmt("@SYS82282", "@SYS7869") + ': ' + locPhone;
            }
            locEmail                                = locKCS_KBVRequestTable.displayEmail();        // @SYS5845
            if(locEmail)
            {
                if(clsRequestTmp.ContactInformation)
                {
                    clsRequestTmp.ContactInformation += ', ';
                }
                clsRequestTmp.ContactInformation += strFmt("@SYS82282", "@SYS5845") + ': ' + locEmail;
            }
            locAddressing      = locKCS_KBVRequestTable.displayAddress();
            if(locAddressing)
            {
                if(clsRequestTmp.ContactInformation)
                {
                    clsRequestTmp.ContactInformation += '\n';
                }
                clsRequestTmp.ContactInformation += locAddressing;
            }

            clsRequestTmp.smmBusRelAccount          = smmBusRelTable::findByParty(locContactPerson.DirPartyTable().RecId).BusRelAccount;    // @SYS80106
            clsRequestTmp.CustTableAccount          = CustTable::findByPartyRecId(locContactPerson.DirPartyTable().RecId).AccountNum;       // @SYS7149
            clsRequestTmp.KCS_KBVReceiptDate        = locKCS_KBVRequestTable.KCS_KBVReceiptDate;                                            // @NDX:NXAReceiptDate
            clsRequestTmp.KCS_KBVModifiedDate       = locKCS_KBVRequestTable.KCS_KBVModifiedDate;                                           // @NDX:NXAModifiedDate
            clsRequestTmp.KCS_KBVModifiedBy         = locKCS_KBVRequestTable.KCS_KBVModifiedBy;                                             // @NDX:NXAEditor
            if(clsRequestTmp.KCS_KBVModifiedBy)
            {
                clsRequestTmp.KCS_KBVModifiedByName = HcmWorker::find(clsRequestTmp.KCS_KBVModifiedBy).name();
            }
            clsRequestTmp.KCS_KBVDeliveryDate       = locKCS_KBVRequestTable.KCS_KBVDeliveryDate;                                           // @NDX:NXATenderClosingDate
            clsRequestTmp.KCS_KBVSmmSalesUnitIndoor = locKCS_KBVRequestTable.KCS_KBVSmmSalesUnitIndoor;                                     // @NDX:NXASalesUnitIndoor
            clsRequestTmp.AVAWorkerSalesTakerName   = HCMWorker::find(locKCS_KBVRequestTable.AVAWorkerSalesTaker).name();                   // @SYS320666
            clsRequestTmp.AVAWorkerSalesTakerDate   = locKCS_KBVRequestTable.AVAWorkerSalesTakerDate;                                       // @NDX:NXAResponsibleSince

            clsRequestTmp.insert();
            clsAdditionalInfoLevel++;
        }
    }
}

/// <summary>
///    AVA <c>insertTmpTableDataRelations</c> method.
/// </summary>
public void insertTmpTableDataRelations()
{
    KCS_KBVRelationsToBV    locKCS_KBVRelationsToBV;
    KCS_KBVRelations        locKCS_KBVRelations;
    DirPartyTable           locDirPartyTable;
    ContactPerson           locContactPerson;
    PhoneMobile             locPhoneMobile;
    Phone                   locPhone;
    Email                   locEmail;
    Addressing              locAddressing;

    if(clsKCS_KBVBuildingProjectTable.RecId)
    {
        this.setTransactionConnection(clsRelationTmp);

        clsAdditionalInfoLevel = 400;

        while select locKCS_KBVRelationsToBV
        where   locKCS_KBVRelationsToBV.KCS_KBVBuildingProjectID == clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
            join    locKCS_KBVRelations
            where   locKCS_KBVRelations.KCS_KBVRelationID == locKCS_KBVRelationsToBV.KCS_KBVRelationID
        {
            clsRelationTmp.clear();
            clsRelationTmp.AdditionalInfoNo         = clsAdditionalInfoLevel;
            clsRelationTmp.KCS_KBVBuildingProjectID = clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;

            clsRelationTmp.KCS_KBVRelationID        = locKCS_KBVRelationsToBV.KCS_KBVRelationID;

            clsRelationTmp.NDX_BVRelationType       = locKCS_KBVRelations.NDX_BVRelationType;           // @NDX:NXARelationType
            clsRelationTmp.Description              = locKCS_KBVRelations.Description;                  // @SYS7576
            clsRelationTmp.KCS_KBVSalesPriority     = locKCS_KBVRelations.KCS_KBVSalesPriority;         // @NDX:NXASalesRelationPriority

            locDirPartyTable                        = locKCS_KBVRelationsToBV.dirPartyTablePrefered();
            clsRelationTmp.DirPartyId               = locDirPartyTable.RecId;
            clsRelationTmp.DirPartyTableName        = locDirPartyTable.Name;

            locContactPerson                        = locKCS_KBVRelationsToBV.contactPerson();
            if(locContactPerson.RecId)
            {
                clsRelationTmp.ContactPersonId      = locContactPerson.ContactPersonId;
                clsRelationTmp.ContactPersonName    = locContactPerson.personName();
            }
            locPhoneMobile                          = locKCS_KBVRelationsToBV.displayKCS_KBVRelationsMobile();          // @SYS27784
            if(locPhoneMobile)
            {
                if(clsRelationTmp.ContactInformation)
                {
                    clsRelationTmp.ContactInformation += ', ';
                }
                clsRelationTmp.ContactInformation += strFmt("@SYS82282", "@SYS27784") + ': ' + locPhoneMobile;
            }
            locPhone                                = locKCS_KBVRelationsToBV.displayKCS_KBVRelationsPhone();           // @SYS7869
            if(locPhone)
            {
                if(clsRelationTmp.ContactInformation)
                {
                    clsRelationTmp.ContactInformation += ', ';
                }
                clsRelationTmp.ContactInformation += strFmt("@SYS82282", "@SYS7869") + ': ' + locPhone;
            }
            locEmail                                = locKCS_KBVRelationsToBV.displayKCS_KBVRelationsEmail();           // @SYS5845
            if(locEmail)
            {
                if(clsRelationTmp.ContactInformation)
                {
                    clsRelationTmp.ContactInformation += ', ';
                }
                clsRelationTmp.ContactInformation += strFmt("@SYS82282", "@SYS5845") + ': ' + locEmail;
            }
            locAddressing      = locKCS_KBVRelationsToBV.displayAddress();
            if(locAddressing)
            {
                if(clsRelationTmp.ContactInformation)
                {
                    clsRelationTmp.ContactInformation += '\n';
                }
                clsRelationTmp.ContactInformation += locAddressing;
            }

            clsRelationTmp.insert();
            clsAdditionalInfoLevel++;
        }
    }
}

/// <summary>
///    AVA <c>insertTmpTableDataQuotations</c> method.
/// </summary>
public void insertTmpTableDataQuotations()
{
    SalesQuotationTable locSalesQuotationTable;

    if(clsKCS_KBVBuildingProjectTable.RecId)
    {
        this.setTransactionConnection(clsQuotationTmp);

        clsAdditionalInfoLevel = 500;

        while select locSalesQuotationTable
        where locSalesQuotationTable.KCS_KBVBuildingProjectID == clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
        {
            clsQuotationTmp.clear();
            clsQuotationTmp.AdditionalInfoNo            = clsAdditionalInfoLevel;
            clsQuotationTmp.KCS_KBVBuildingProjectID    = locSalesQuotationTable.KCS_KBVBuildingProjectID;
            clsQuotationTmp.DetailRecId                 = locSalesQuotationTable.RecId;
            clsQuotationTmp.QuotationId                 = locSalesQuotationTable.QuotationId;
            clsQuotationTmp.QuotationName               = locSalesQuotationTable.QuotationName;
            clsQuotationTmp.QuotationStatus             = locSalesQuotationTable.QuotationStatus;
            clsQuotationTmp.QuotationType               = locSalesQuotationTable.QuotationType;

            clsQuotationTmp.KCS_KBVRequestId            = locSalesQuotationTable.KCS_KBVRequestId;
            clsQuotationTmp.KCS_KBVSubject              = locSalesQuotationTable.KCS_KBVSubject;

            clsQuotationTmp.insert();
            clsAdditionalInfoLevel++;
        }
    }
}

/// <summary>
///    AVA <c>buildingProjectKnownBy</c> method.
/// </summary>
/// <returns>
///     <c>String255</c> as type
/// </returns>
public String255 buildingProjectKnownBy()
{
    String255                   retVal;

    KCS_KBVRequestTable         locDataAreaIdBuffer;
    String255                   locKnownBy;
    KCS_KBVParameters           locKCS_KBVParameters;
    DataAreaId                  locDataAreaIdRico;
    //NDX_RicoKalkBVNr            ndx_RicoKalkBVNr;

    locKCS_KBVParameters    = KCS_KBVParameters::find();
    locDataAreaIdRico       = locKCS_KBVParameters.AVADataAreaIdRICO;

    while select crosscompany : clsAllBPCompaniesAll DataAreaId
    from    locDataAreaIdBuffer
    group by DataAreaId
    where   locDataAreaIdBuffer.KCS_KBVBuildingProjectID    == clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
        &&  locDataAreaIdBuffer.DataAreaId                  != curext()
    {
        if (confind(clsAllBPCompaniesAll, locDataAreaIdBuffer.DataAreaId))
        {
            if(locKnownBy)
            {
                locKnownBy += ', ';
            }
            locKnownBy += locDataAreaIdBuffer.DataAreaId;
        }
    }
    if (locKnownBy)
    {
        locKnownBy = strFmt("@SYS82282", "@NDX:NXABPKnownIn") + ' ' + locKnownBy;
    }
    /*
    ndx_RicoKalkBVNr = NDX_KBV2RicoKalkMap::find(myKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID).RicoKalkBVNr;
    if (ndx_RicoKalkBVNr)
    {
        locKnownBy += " (" + SysLabel::labelId2String2(literalstr("@KBV437"), language) + " " + int2str(ndx_RicoKalkBVNr) + ")";
    }
    */
    retVal = locKnownBy;

    return retVal;
}
